"""Archetypes for life, Earth and space science, English, learning-to-learn and personal development.
Card-sorting labs with checked answers; these topics are not numeric, so items are concept questions."""
from items import num, mc, V
from arch_math import A
def S(name, dom, kw, cap, bins, items, kid, adult, worked, qs, numeric=False, p=None, m=None):
    return A(name, dom, kw, V("sorter", cap, bins=bins, items=items), kid, adult, worked, p or qs[:3], m or qs[3:], numeric)
